	Real plus = highPlus > lowPlus ? highPlus : lowPlus;
	Real lowMinus = TheTerrainLogic->getGroundHeight(x - TheWritableGlobalData->m_cameraTerrainSampleRadiusForHeight, y - TheWritableGlobalData->m_cameraTerrainSampleRadiusForHeight);
	Real highMinus = TheTerrainLogic->getGroundHeight(x + TheWritableGlobalData->m_cameraTerrainSampleRadiusForHeight, y - TheWritableGlobalData->m_cameraTerrainSampleRadiusForHeight);
