void W3DView::constrainPosition(Coord3D *position)
{
	if (!m_zoomLimited)
		return;
	Vector3 offset = m_3DCamera->Get_Position();
	Vector3 viewPosition;
	viewPosition.X = m_pos.x;
	viewPosition.Y = m_pos.y;
	viewPosition.Z = m_pos.z;
	offset.X -= viewPosition.X;
	offset.Y -= viewPosition.Y;
	offset.Z -= viewPosition.Z;
	offset.Z = 0;
	offset.X = offset.X * 0.25f;
	offset.Y = offset.Y * 0.25f;
	offset.Z = offset.Z * 0.25f;
	position->x += offset.X;
	position->y += offset.Y;
	m_cameraSettings.constrainPosition(position);
	position->x -= offset.X;
	position->y -= offset.Y;
}

