View::WorldToScreenReturn W3DView::worldToScreenTriReturn(const Coord3D *w, ICoord2D *s)
{
	if (w == 0 || s == 0 || m_3DCamera == 0)
		return WTS_INVALID;

	Vector3 world(w->x, w->y, w->z);
	Vector3 screen;
	CameraClass::ProjectionResType projection = m_3DCamera->Project(screen, world);
	if (projection == CameraClass::OUTSIDE_NEAR_CLIP)
	{
		s->x = 0;
		s->y = 0;
		return WTS_INVALID;
	}

	W3DLogicalScreenToPixelScreen(screen.X, screen.Y, &s->x, &s->y, getWidth(), getHeight());
	s->x += m_originX;
	s->y += m_originY;
	return projection != CameraClass::INSIDE_FRUSTUM ? WTS_OUTSIDE_FRUSTUM : WTS_INSIDE_FRUSTUM;
}

