void W3DView::cameraModFinalTimeMultiplier(Int finalMultiplier)
{
	if (m_doingZoomCamera)
		m_zcInfo.endTimeMultiplier = finalMultiplier;
	if (m_doingFovCamera)
		m_fovInfo.endTimeMultiplier = finalMultiplier;
	if (m_doingPitchCamera)
		m_pcInfo.endTimeMultiplier = finalMultiplier;
	if (m_doingScriptedPitch)
		m_scriptedPitchInfo.endTimeMultiplier = finalMultiplier;
	if (m_doingRotateCamera)
		m_rcInfo.endTimeMultiplier = finalMultiplier;
	if (m_cameraMovementMode == 1) {
		Int i;
		Real curDistance = 0;
		for (i = 0; i < m_pathNumValues; i++) {
			curDistance += m_pathSegmentLengths[i];
			Real factor2 = curDistance / m_pathTotalDistance;
			double factor1 = 1.0 - factor2;
			m_pathTimeMultipliers[i + 1] = Float_To_Long((float)floor(0.5 + m_pathTimeMultipliers[i + 1] * factor1 + (double)(float)finalMultiplier * factor2));
		}
	} else {
		m_timeMultiplier = finalMultiplier;
	}
}

