// FUNCTION: BFME2 0x00086CDA size=153 name=?rva00086CDA@Rva00086761CameraMove@@QAEXXZ evidence=?:placeholder tier=A
void W3DView::zoomCameraOneFrame()
{
	++m_zcInfo.curFrame;
	if (TheWritableGlobalData->m_disableCameraMovements) {
		if (m_zcInfo.curFrame < m_zcInfo.numFrames)
			return;
		m_doingZoomCamera = false;
		return;
	}
	if (m_zcInfo.curFrame <= m_zcInfo.numFrames) {
		Real factor = m_zcInfo.ease((Real)m_zcInfo.curFrame / (Real)m_zcInfo.numFrames);
		Real start = m_zcInfo.startZoom;
		Real range = m_zcInfo.endZoom - start;
		m_zoom = range * factor + start;
	}
	if (m_zcInfo.curFrame < m_zcInfo.numFrames)
		return;
	m_zoom = m_zcInfo.endZoom;
	m_doingZoomCamera = false;
}

