void W3DView::getPickRay(const ICoord2D *screen, Vector3 *rayStart, Vector3 *rayEnd)
{
	Real logX, logY;
	PixelScreenToW3DLogicalScreen(screen->x - m_originX, screen->y - m_originY, &logX, &logY, getWidth(), getHeight());
	*rayStart = m_3DCamera->Get_Position();
	m_3DCamera->Un_Project(*rayEnd, Vector2(logX, logY));
	rayEnd->X -= rayStart->X;
	rayEnd->Y -= rayStart->Y;
	rayEnd->Z -= rayStart->Z;
	rayEnd->Normalize();
	*rayEnd *= m_3DCamera->Get_Depth();
	*rayEnd += *rayStart;
}

